public class ResponderGatewayFactory(string resourceName = null, Action<Humidifier.RTBFabric.ResponderGateway> factoryAction = null) : ResourceFactory<Humidifier.RTBFabric.ResponderGateway>(resourceName)
{

    internal InnerResponderGatewayTrustStoreConfigurationFactory TrustStoreConfigurationFactory { get; set; }

    internal InnerResponderGatewayManagedEndpointConfigurationFactory ManagedEndpointConfigurationFactory { get; set; }

    internal InnerResponderGatewayListenerConfigFactory ListenerConfigFactory { get; set; }

    protected override Humidifier.RTBFabric.ResponderGateway Create()
    {
        var responderGatewayResult = CreateResponderGateway();
        factoryAction?.Invoke(responderGatewayResult);

        return responderGatewayResult;
    }

    private Humidifier.RTBFabric.ResponderGateway CreateResponderGateway()
    {
        var responderGatewayResult = new Humidifier.RTBFabric.ResponderGateway
        {
            GivenName = InputResourceName,
        };

        return responderGatewayResult;
    }
    public override void CreateChildren(Humidifier.RTBFabric.ResponderGateway result)
    {
        base.CreateChildren(result);

        result.TrustStoreConfiguration ??= TrustStoreConfigurationFactory?.Build();
        result.ManagedEndpointConfiguration ??= ManagedEndpointConfigurationFactory?.Build();
        result.ListenerConfig ??= ListenerConfigFactory?.Build();
    }

} // End Of Class

